// Checks clipboard list conversion and its plain-text safeguards.
using AntiNotepad.Editor;

namespace AntiNotepad;

internal static partial class SelfTest
{
    private static bool PasteChecks(out string report)
    {
        var failures = new List<string>();
        void Check(bool condition, string name) { if (!condition) failures.Add(name); }
        var plain = "test from ai chat\ntest 2 from ai chat\ntest 3\ntest2 again\ntest from ai chat\ntest 2\ntest3\ntest 2";
        var html = "<ul data-pm-slice=\"3 1 []\"><li><p>test from ai chat</p><ul><li><p>test 2 from ai chat</p><ul><li><p>test 3</p></li></ul></li><li><p>test2 again</p></li></ul></li></ul><ol><li><p>test from ai chat</p><ol><li><p>test 2</p><ol><li><p>test3</p></li></ol></li><li><p>test 2</p></li></ol></li></ol><p></p>";
        var expected = "- test from ai chat\n  - test 2 from ai chat\n    - test 3\n  - test2 again\n1. test from ai chat\n  1. test 2\n    1. test3\n  2. test 2";
        ClipSnapshot Snapshot(string? text, string? markup) => new(text, markup, [], false, []);
        Check(PasteEngine.Upgrade(Snapshot(plain, html)) == expected, "captured list");
        Check(PasteEngine.Upgrade(Snapshot("- Alpha\n- Beta\n  - Nested item\n- Gamma\n\n1. First\n2. Second\n   1. Nested step", "<p>- Alpha</p>")) is null, "markdown source");
        var captureCPlain = "Both are told, and both messages were delivered, though neither is confirmed read.\n\nMaster 6 got the facts and three asks:\nResolve the A23 card from the branch version at merge.\nAdd only an item’s own files on later merges.\nWatch for the untracked A21 lab pages, which could be swept in the same way.\nPStack Manager was asked to plan a permanent fix. I suggested these as starting points:\nA merge preflight that fails when a dev commit touches the cards of an item that has no branch.\nA staged-files allowlist at merge.\napprove.ps1 accepting a card that is already tracked.\nA home for the untracked lab pages.";
        var captureCHtml = "<p dir=\"ltr\">Both are told, and both messages were delivered, though neither is confirmed read.</p><ul dir=\"ltr\"><li><strong>Master 6</strong> got the facts and three asks:<ul dir=\"ltr\"><li>Resolve the A23 card from the branch version at merge.</li><li>Add only an item’s own files on later merges.</li><li>Watch for the untracked A21 lab pages, which could be swept in the same way.</li></ul></li><li><strong>PStack Manager</strong> was asked to plan a permanent fix. I suggested these as starting points:<ul dir=\"ltr\"><li>A merge preflight that fails when a dev commit touches the cards of an item that has no branch.</li><li>A staged-files allowlist at merge.</li><li><code dir=\"ltr\">approve.ps1</code> accepting a card that is already tracked.</li><li>A home for the untracked lab pages.</li></ul></li></ul>";
        var captureCExpected = "Both are told, and both messages were delivered, though neither is confirmed read.\n\n- **Master 6** got the facts and three asks:\n  - Resolve the A23 card from the branch version at merge.\n  - Add only an item’s own files on later merges.\n  - Watch for the untracked A21 lab pages, which could be swept in the same way.\n- **PStack Manager** was asked to plan a permanent fix. I suggested these as starting points:\n  - A merge preflight that fails when a dev commit touches the cards of an item that has no branch.\n  - A staged-files allowlist at merge.\n  - `approve.ps1` accepting a card that is already tracked.\n  - A home for the untracked lab pages.";
        Check(PasteEngine.Upgrade(Snapshot(captureCPlain, captureCHtml)) == captureCExpected, "captured paragraph and list");
        Check(PasteEngine.Upgrade(Snapshot("A\nB", "<ul><li>A</li></ul><p>B</p>")) == "- A\n\nB", "paragraph after list");
        Check(PasteEngine.Upgrade(Snapshot("A\nB\nC", "<p>A</p><p>B</p><ul><li>C</li></ul>")) == "A\n\nB\n\n- C", "paragraphs before list");
        Check(PasteEngine.Upgrade(Snapshot("Before\nItem\nAfter", "<div>Before<ul><li>Item</li></ul>After</div>")) == "Before\n\n- Item\n\nAfter", "list inside div");
        Check(PasteEngine.Upgrade(Snapshot("Title\nA", "<h2>Title</h2><ul><li>A</li></ul>")) == "## Title\n\n- A", "heading and list");
        Check(PasteEngine.Upgrade(Snapshot("A\nB\nC", "<p>A<br>B</p><ul><li>C</li></ul>")) == "A\nB\n\n- C", "paragraph line break");
        Check(PasteEngine.Upgrade(Snapshot("A\nB", "<p>A</p><ul><li>B</li></ul><p>")) is null, "unclosed block");
        Check(PasteEngine.Upgrade(Snapshot("A\nB", "<p>A</p><ul><li>C</li></ul>")) is null, "word mismatch");
        Check(PasteEngine.Upgrade(Snapshot("plain", "<p>plain</p>")) is null, "plain text");
        Check(PasteEngine.Upgrade(Snapshot("A & B\nC", "<ul><li>A &amp; B<ol><li>C</li></ol></li></ul>")) == "- A & B\n  1. C", "mixed and entities");
        Check(PasteEngine.Upgrade(Snapshot("A", "<ul><li></li><li>A</li></ul>")) == "- \n- A", "empty item");
        var fragment = "<ul><li>é</li></ul>";
        var header = "Version:1.0\r\nStartFragment:0000000000\r\nEndFragment:0000000000\r\n";
        var prefix = header + "<html>";
        var start = System.Text.Encoding.UTF8.GetByteCount(prefix);
        var end = start + System.Text.Encoding.UTF8.GetByteCount(fragment);
        header = $"Version:1.0\r\nStartFragment:{start:D10}\r\nEndFragment:{end:D10}\r\n";
        Check(PasteEngine.Upgrade(Snapshot("é", header + "<html>" + fragment + "</html>")) == "- é", "byte offsets");
        Check(PasteEngine.Upgrade(Snapshot("  A", "<ul><li>A</li></ul>")) is null, "indent guard");
        Check(PasteEngine.Upgrade(Snapshot("A", "<div style=\"white-space: pre-wrap\"><ul><li>A</li></ul></div>")) is null, "pre style guard");
        Check(PasteEngine.Upgrade(Snapshot("A", "<pre><ul><li>A</li></ul></pre>")) is null, "preformatted");
        Check(PasteEngine.Upgrade(Snapshot("A", "<ul><li>A")) is null, "bad html");
        Check(PasteEngine.Upgrade(new(null, null, [], true, [])) is null, "image placeholder");
        Check(PasteEngine.Upgrade(new(null, null, [], false, ["file"])) is null, "files placeholder");
        Check(PasteEngine.Upgrade(Snapshot("A B C D", "<p><u> A </u><em>B</em> <del>C</del> <strong><i>D</i></strong></p>")) == "++A++ *B* ~~C~~ ***D***", "inline marks and spaces");
        Check(PasteEngine.Upgrade(Snapshot("Name https://example.com", "<p><a href='https://example.com'>Name</a> <a href='https://example.com'>https://example.com</a></p>")) == "Name (https://example.com) https://example.com", "links");
        Check(PasteEngine.Upgrade(Snapshot("A\tB\nX\t🟢", "<table><tr><td>A</td><td>B</td></tr><tr><td>X</td><td>🟢</td></tr></table>")) == "| A   | B   |\n| --- | --- |\n| X   | 🟢  |", "table alignment");
        Check(PasteEngine.Upgrade(Snapshot("A|B", "<table><tr><td>A|B</td></tr></table>")) == "| A\\|B |\n| ---- |", "table escaped pipe");
        Check(PasteEngine.Upgrade(Snapshot("A", "<table><tr><td colspan='2'>A</td></tr></table>")) is null, "table colspan");
        Check(PasteEngine.Upgrade(Snapshot("A", "<ul><li><table><tr><td>A</td></tr></table></li></ul>")) is null, "table inside list");
        Check(PasteEngine.Upgrade(Snapshot("A\tB", "<table><tr><td>A<td>B</table>")) == "| A   | B   |\n| --- | --- |", "optional table closures");
        Check(PasteEngine.Upgrade(Snapshot("If you say\tWhat happens\tUndo?\nTell Master 6\tI message the Master 6 chat with the facts and the two fixes: merge adds only the item’s own files, and approve.ps1 accepts an already-tracked card\t🟢 Just a message\nLeave it\tNothing sent; I handle A23 alone and A22 hits the same wall\t🟢 Nothing changed", "<table><thead><tr><th scope=\"col\">If you say</th><th scope=\"col\">What happens</th><th scope=\"col\">Undo?</th></tr></thead><tbody><tr><td>Tell Master 6</td><td>I message the Master 6 chat with the facts and the two fixes: merge adds only the item’s own files, and <code dir=\"ltr\">approve.ps1</code> accepts an already-tracked card</td><td>🟢 Just a message</td></tr><tr><td>Leave it</td><td>Nothing sent; I handle A23 alone and A22 hits the same wall</td><td>🟢 Nothing changed</td></tr></tbody></table>")) == "| If you say    | What happens                                                                                                                                          | Undo?              |\n| ------------- | ----------------------------------------------------------------------------------------------------------------------------------------------------- | ------------------ |\n| Tell Master 6 | I message the Master 6 chat with the facts and the two fixes: merge adds only the item’s own files, and `approve.ps1` accepts an already-tracked card | 🟢 Just a message  |\n| Leave it      | Nothing sent; I handle A23 alone and A22 hits the same wall                                                                                           | 🟢 Nothing changed |", "capture D");
        Check(PasteEngine.Upgrade(Snapshot("What happened 🟢\n\nThe A21 merge commit e2bb364 (17 Nov, 00:23) lists, in its own message: “Also: A22/A23 cards, launch.json, STATUS and pending refresh.”\nThe A23 card was committed to dev there, in its early Request state, together with .claude/launch.json.\nMaster 6 had created that card earlier, so it sat untracked in the main checkout. The merge commit swept it in.\nThe merge step in .claude/skills/merge-task/SKILL.md says to commit only STATUS and lessons. The merge also took the cards and launch.json, so a broader add was used.\nbranches.md says a card stays untracked until Approve, then moves into the item’s branch.\nThat is why tools/approve.ps1 refused: it requires an untracked card.\n\nWhat could go wrong if left unchecked 🟡\n\nApprove breaks for any item whose card gets swept in. I had to do the branch and card steps by hand, which skips the script’s checks (cap, files overlap).\nTwo copies of the card diverge. Dev holds the old Request-only version, and the item branch holds the real one. The merge back is a conflict on a file nobody should have to resolve.\nDev carries unapproved cards. An item can look started in dev’s history before the user said Approve. The same applies to launch.json.\nNoise in the A21 merge. The “one clean merge per item” history now mixes in other items’ files, which defeats the purpose of tracing a break to one item.\nSame hit as A22: its card was committed separately (90ef390), so it is already tracked and will block approve.ps1 the same way.\nA21’s lab pages (tools/playground/a21-*.html) are still untracked, so the same sweep could happen again.", "<p dir=\"ltr\"><strong>What happened 🟢</strong></p><ul dir=\"ltr\"><li>The A21 merge commit <code dir=\"ltr\">e2bb364</code> (17 Nov, 00:23) lists, in its own message: “Also: A22/A23 cards, launch.json, STATUS and pending refresh.”</li><li>The A23 card was committed to dev there, in its early Request state, together with <code dir=\"ltr\">.claude/launch.json</code>.</li><li>Master 6 had created that card earlier, so it sat untracked in the main checkout. The merge commit swept it in.</li><li>The merge step in <code dir=\"ltr\">.claude/skills/merge-task/SKILL.md</code> says to commit only STATUS and lessons. The merge also took the cards and <code dir=\"ltr\">launch.json</code>, so a broader add was used.</li><li><code dir=\"ltr\">branches.md</code> says a card stays untracked until Approve, then moves into the item’s branch.</li><li>That is why <code dir=\"ltr\">tools/approve.ps1</code> refused: it requires an untracked card.</li></ul><p dir=\"ltr\"><strong>What could go wrong if left unchecked 🟡</strong></p><ul dir=\"ltr\"><li><strong>Approve breaks</strong> for any item whose card gets swept in. I had to do the branch and card steps by hand, which skips the script’s checks (cap, files overlap).</li><li><strong>Two copies of the card diverge.</strong> Dev holds the old Request-only version, and the item branch holds the real one. The merge back is a conflict on a file nobody should have to resolve.</li><li><strong>Dev carries unapproved cards.</strong> An item can look started in dev’s history before the user said Approve. The same applies to <code dir=\"ltr\">launch.json</code>.</li><li><strong>Noise in the A21 merge.</strong> The “one clean merge per item” history now mixes in other items’ files, which defeats the purpose of tracing a break to one item.</li><li><strong>Same hit as A22:</strong> its card was committed separately (<code dir=\"ltr\">90ef390</code>), so it is already tracked and will block <code dir=\"ltr\">approve.ps1</code> the same way.</li><li><strong>A21’s lab pages</strong> (<code dir=\"ltr\">tools/playground/a21-*.html</code>) are still untracked, so the same sweep could happen again.</li></ul>")) == "**What happened 🟢**\n\n- The A21 merge commit `e2bb364` (17 Nov, 00:23) lists, in its own message: “Also: A22/A23 cards, launch.json, STATUS and pending refresh.”\n- The A23 card was committed to dev there, in its early Request state, together with `.claude/launch.json`.\n- Master 6 had created that card earlier, so it sat untracked in the main checkout. The merge commit swept it in.\n- The merge step in `.claude/skills/merge-task/SKILL.md` says to commit only STATUS and lessons. The merge also took the cards and `launch.json`, so a broader add was used.\n- `branches.md` says a card stays untracked until Approve, then moves into the item’s branch.\n- That is why `tools/approve.ps1` refused: it requires an untracked card.\n\n**What could go wrong if left unchecked 🟡**\n\n- **Approve breaks** for any item whose card gets swept in. I had to do the branch and card steps by hand, which skips the script’s checks (cap, files overlap).\n- **Two copies of the card diverge.** Dev holds the old Request-only version, and the item branch holds the real one. The merge back is a conflict on a file nobody should have to resolve.\n- **Dev carries unapproved cards.** An item can look started in dev’s history before the user said Approve. The same applies to `launch.json`.\n- **Noise in the A21 merge.** The “one clean merge per item” history now mixes in other items’ files, which defeats the purpose of tracing a break to one item.\n- **Same hit as A22:** its card was committed separately (`90ef390`), so it is already tracked and will block `approve.ps1` the same way.\n- **A21’s lab pages** (`tools/playground/a21-*.html`) are still untracked, so the same sweep could happen again.", "capture E");
        report = string.Join(", ", failures);
        return failures.Count == 0;
    }
}


